package com.gomgomapps.math.core;
import java.util.*;import java.math.*;import org.junit.Test;import static org.junit.Assert.*;
public class DecimalPowerTenTest {
 @Test public void finiteDomainsHaveExactValuesAndThreePlaceAnswers(){var l=GlobalCurriculum.limits("england-primary-2021-v1",DecimalPowerTen.MUL,6);assertEquals(300000,DecimalPowerTen.count(DecimalPowerTen.MUL,l));assertEquals(11100,DecimalPowerTen.count(DecimalPowerTen.DIV,l));for(String id:List.of(DecimalPowerTen.MUL,DecimalPowerTen.DIV))for(int i=0;i<DecimalPowerTen.count(id,l);i++){Question q=DecimalPowerTen.at(id,i,l);String[] v=q.prompt.split(" ");BigDecimal x=new BigDecimal(v[0]),d=new BigDecimal(v[2]),answer=id.equals(DecimalPowerTen.MUL)?x.multiply(d):x.divide(d);assertEquals(answer.stripTrailingZeros().toPlainString(),q.answers[0]);assertTrue(answer.stripTrailingZeros().scale()<=3);assertTrue(new Checker().check(q,List.of(),List.of(q.answers[0])).correct());}for(int power:List.of(10,100,1000)){assertEquals("0",DecimalPowerTen.make(DecimalPowerTen.MUL,"0.000",power).answers[0]);assertEquals("0",DecimalPowerTen.make(DecimalPowerTen.DIV,"0",power).answers[0]);}assertEquals("99999",DecimalPowerTen.make(DecimalPowerTen.MUL,"99.999",1000).answers[0]);try{DecimalPowerTen.make(DecimalPowerTen.DIV,"0.001",1000);fail();}catch(IllegalArgumentException expected){}}
 @Test public void reusedArithmeticHelpUsesOnlyPublicOperands(){for(String id:List.of(DecimalPowerTen.MUL,DecimalPowerTen.DIV)){Question q=new Question(id,"4.20"+(id.equals(DecimalPowerTen.MUL)?" × ":" ÷ ")+"100","poison","999");HelpPlan h=HelpPlan.forQuestion(q);assertEquals(id.equals(DecimalPowerTen.MUL)?6:7,h.size());assertFalse(h.canTransfer());List<String> entries=id.equals(DecimalPowerTen.MUL)?List.of("4.2","100","2","420","42000","420"):List.of("4.2","100","2","100","420","4.2","0.042");for(int i=0;i<entries.size();i++){assertTrue(h.step(i).accepts(entries.get(i)));assertFalse(h.step(i).accepts(""));}assertTrue(h.step(h.size()-1).before.contains(id.equals(DecimalPowerTen.MUL)?"r":"u"));}}
 @Test public void threeSelectedGradeLinksAndFreshConditions(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();for(String id:List.of("decimalDigitValue",DecimalPowerTen.MUL,DecimalPowerTen.DIV)){assertTrue(pack.inGrade(id,6));Generator g=new Generator(new Random(92));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(id,recent,false,GlobalCurriculum.limits(pack.id,id,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertFalse(HelpPlan.forQuestion(q).canTransfer());}}}
}
